def flood_fill_8way(grid, start_cell, color):
    """Find all 8-way connected cells"""
    rows, cols = len(grid), len(grid[0])
    visited = set()
    queue = [start_cell]
    result = []
    while queue:
        r, c = queue.pop(0)
        if (r, c) in visited:
            continue
        if not (0 <= r < rows and 0 <= c < cols and grid[r][c] == color):
            continue
        visited.add((r, c))
        result.append((r, c))
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if (nr, nc) not in visited and grid[nr][nc] == color:
                        queue.append((nr, nc))
    return result

